using FluNET.Prompt;using FluNET.Prompt.Surface;namespace FluNET.Language.Resources;
public enum ResourceReadIntent{Get,Load}public enum ResourceCapability{FileRead,NetworkRead,EnvironmentRead,SecretRead,DatabaseRead}public sealed record ResourceProviderContext(ResourceDescriptor Descriptor,string OutputVariable,SurfaceCommandSyntax SurfaceCommand,SurfaceValueSyntax Source,PromptGrammar Grammar,ResourceReadIntent Intent);public sealed record ResourceProviderResult(IReadOnlyList<CommandSyntax> Commands,string? ErrorCode=null,string? ErrorMessage=null){public bool IsSuccess=>ErrorCode is null;public static ResourceProviderResult Error(string c,string m)=>new([],c,m);}public interface IResourceProvider{string Id{get;}IReadOnlyList<ResourceCapability>RequiredCapabilities=>[];bool CanHandle(ResourceDescriptor d);ResourceProviderResult LowerRead(ResourceProviderContext c);}public interface IResourceProviderRegistry{IReadOnlyList<IResourceProvider>Providers{get;}IResourceProvider? Resolve(ResourceDescriptor d);}internal sealed record ResourceProviderRegistration(Type ProviderType,Func<IServiceProvider,IResourceProvider>Create);
public sealed class ResourceProviderRegistry:IResourceProviderRegistry{private readonly IResourceProvider[]_providers;internal ResourceProviderRegistry(IServiceProvider s,IEnumerable<ResourceProviderRegistration>r){_providers=new IResourceProvider[]{new FileResourceProvider(),new HttpResourceProvider(),new EnvironmentResourceProvider(),new SecretResourceProvider(),new SqlResourceProvider()}.Concat(r.Select(x=>x.Create(s))).ToArray();string[]d=_providers.GroupBy(x=>x.Id,StringComparer.OrdinalIgnoreCase).Where(g=>g.Count()>1).Select(g=>g.Key).ToArray();if(d.Length>0)throw new LanguageDefinitionException($"Resource provider ids must be unique: {string.Join(", ",d)}.");}public IReadOnlyList<IResourceProvider>Providers=>_providers;public IResourceProvider?Resolve(ResourceDescriptor d){IResourceProvider[]m=_providers.Where(p=>p.CanHandle(d)).ToArray();return m.Length switch{0=>null,1=>m[0],_=>throw new LanguageDefinitionException($"Resource '{d.Reference.DisplayName}' matches multiple providers: {string.Join(", ",m.Select(i=>i.Id))}.")};}}
public sealed class FileResourceProvider:IResourceProvider{public string Id=>"core.file";public IReadOnlyList<ResourceCapability>RequiredCapabilities=>[ResourceCapability.FileRead];public bool CanHandle(ResourceDescriptor d)=>d.Reference is FileResourceReference;public ResourceProviderResult LowerRead(ResourceProviderContext c){FileResourceReference f=(FileResourceReference)c.Descriptor.Reference;if(f.IsPattern){if(c.Descriptor.Format!=ResourceFormat.Json)return ResourceProviderResult.Error("FLN225",$"Glob LOAD currently supports JSON patterns; '{c.Descriptor.Format}' needs a collection codec.");return new([Cmd("LOADGLOB",c,f.Path)]);}string v=c.Descriptor.Format switch{ResourceFormat.Csv=>"LOADCSV",ResourceFormat.Xml=>"LOADXML",ResourceFormat.Binary=>"LOADBINARY",ResourceFormat.Image=>"LOADIMAGE",_=>string.Empty};if(v.Length>0)return new([Cmd(v,c,f.Path)]);string q=c.Descriptor.Format switch{ResourceFormat.Json=>"CONFIG",ResourceFormat.Text=>"TEXT",_=>string.Empty};if(q.Length==0)return ResourceProviderResult.Error("FLN224",$"No canonical file decoder is registered for format '{c.Descriptor.Format}'.");return new([new CommandSyntax([T("LOAD",PromptTokenKind.Word,c.SurfaceCommand.Span.Start),T(q,PromptTokenKind.Word,c.Source.Span.Start),T($"[{c.OutputVariable}]",PromptTokenKind.Variable,c.Source.Span.Start),T("FROM",PromptTokenKind.Word,c.Source.Span.Start),T($"{{{f.Path}}}",PromptTokenKind.Reference,c.Source.Span.Start)],c.Grammar)]);}private static CommandSyntax Cmd(string v,ResourceProviderContext c,string p)=>new([T(v,PromptTokenKind.Word,c.SurfaceCommand.Span.Start),T($"[{c.OutputVariable}]",PromptTokenKind.Variable,c.Source.Span.Start),T("FROM",PromptTokenKind.Word,c.Source.Span.Start),T($"{{{p}}}",PromptTokenKind.Reference,c.Source.Span.Start)],c.Grammar);private static PromptToken T(string x,PromptTokenKind k,int s)=>new(x,k,Math.Max(0,s),0);}
